function drawBubble(text, x, y, o = {}) {
  const size = o.size ?? 18;
  const font = `800 ${size}px ${DISPLAY}`;
  const maxW = o.maxW ?? 230;
  const lines = S.wrap(text, maxW, font);
  ctx.save(); ctx.font = font;
