  const k = e.code;
  if (['Space', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(k)) e.preventDefault();
  if (S.scene === 'title') {
    if (k === 'Space' || k === 'Enter') S.startGame();
    return;
  }
  if (S.scene === 'end') {
