import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const exe='/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
const browser=await chromium.launch({headless:true, executablePath:exe, args:['--no-sandbox','--disable-gpu']});
const page=await browser.newPage({viewport:{width:1440,height:900}, deviceScaleFactor:1});
const errs=[];
page.on('pageerror',e=>errs.push('PAGEERROR '+e.message));
page.on('console',m=>{if(m.type()==='error') errs.push('CONSOLE '+m.text())});
await page.goto('http://localhost:3000/',{waitUntil:'load'});
await page.waitForTimeout(400);

// start via visible START button
await page.getByRole('button',{name:'START'}).click();
await page.waitForTimeout(500);

// Act 1 real: hold stare
await page.keyboard.down('Space');
await page.waitForTimeout(2600);
await page.keyboard.up('Space');
await page.waitForTimeout(1400);
console.log('after stare', await page.evaluate(()=>window.SCHULTAG.state));

// jump to act 3 and choose the death potion
await page.evaluate(()=>window.SCHULTAG.act(3));
await page.waitForTimeout(800);
await page.screenshot({path:'screenshots/15-act3-choice.png'});
await page.evaluate(()=>window.SCHULTAG.choose('tod'));
await page.waitForTimeout(2000);
await page.screenshot({path:'screenshots/16-dead-drop.png'});
console.log('dead', await page.evaluate(()=>window.SCHULTAG.state));
await page.waitForTimeout(1000);
await page.screenshot({path:'screenshots/17-ghost.png'});

// jump to act 4, nearly at gate, then let it finish for real
await page.evaluate(()=>{ window.SCHULTAG.act(4); });
await page.waitForTimeout(500);
await page.evaluate(()=>{ window.SCHULTAG.state; });
await page.evaluate(()=>{ const a=window.SCHULTAG; });
await page.evaluate(()=>{ window.__a4 = true; });
// hold run from 95% -> gate
await page.evaluate(()=>{ /* access internal via state not possible */ });
await page.keyboard.down('ArrowRight');
await page.waitForTimeout(1200);
await page.keyboard.up('ArrowRight');
await page.waitForTimeout(900);
await page.screenshot({path:'screenshots/18-act4-gate.png'});
await page.waitForTimeout(3400);
await page.screenshot({path:'screenshots/19-end-real.png'});
console.log('end', await page.evaluate(()=>window.SCHULTAG.state));
const stat = await page.evaluate(()=>({
  stare: document.querySelector('#stat-stare')?.textContent,
  flight: document.querySelector('#stat-flight')?.textContent,
  land: document.querySelector('#stat-land')?.textContent,
  potion: document.querySelector('#stat-potion')?.textContent,
  run: document.querySelector('#stat-run')?.textContent,
  grade: document.querySelector('#stat-grade')?.textContent,
  line: document.querySelector('#end-line')?.textContent,
