import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';
const exe='/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome';
const browser=await chromium.launch({headless:true, executablePath:exe, args:['--no-sandbox','--disable-gpu']});

async function run(label, viewport, opts={}) {
  const ctx = await browser.newContext({ viewport, isMobile:true, hasTouch:true, deviceScaleFactor:2, ...opts });
  const page = await ctx.newPage();
  const errs=[];
  page.on('pageerror',e=>errs.push('PAGEERROR '+e.message));
  page.on('console',m=>{if(m.type()==='error') errs.push('CONSOLE '+m.text())});
  await page.goto('http://localhost:3000/',{waitUntil:'load'});
  await page.waitForTimeout(400);
  await page.getByRole('button',{name:'START'}).tap();
  await page.waitForTimeout(300);
  await page.evaluate(()=>window.SCHULTAG.act(3));
  await page.waitForTimeout(700);
  await page.screenshot({path:`screenshots/m05-${label}-choice.png`});
  // real tap on the mobile choice button
  const btn = page.locator('[data-potion="tod"]');
  console.log(label, 'choice visible', await btn.isVisible());
  await btn.tap();
  await page.waitForTimeout(300);
  console.log(label, 'after tap', JSON.stringify(await page.evaluate(()=>({scene:window.SCHULTAG.scene, a3:window.SCHULTAG.state.a3.phase}))));
  await page.waitForTimeout(1700);
  await page.screenshot({path:`screenshots/m06-${label}-dead.png`});
  // let act4 begin
  await page.waitForTimeout(4000);
  console.log(label, 'scene', await page.evaluate(()=>window.SCHULTAG.scene));
  // run to the gate with Space held, then wait for overlay
  await page.keyboard.down('Space');
  await page.waitForTimeout(8500);
  await page.keyboard.up('Space');
  await page.waitForTimeout(3600);
  console.log(label, 'end?', JSON.stringify(await page.evaluate(()=>({scene:window.SCHULTAG.scene, run:window.SCHULTAG.state.stats.run, a4:window.SCHULTAG.state.a4}))));
  await page.screenshot({path:`screenshots/m07-${label}-end.png`});
  const stat = await page.evaluate(()=>({
    stare: document.querySelector('#statStare')?.textContent,
    flight: document.querySelector('#statFlight')?.textContent,
    land: document.querySelector('#statLand')?.textContent,
    potion: document.querySelector('#statPotion')?.textContent,
    run: document.querySelector('#statRun')?.textContent,
    grade: document.querySelector('#statGrade')?.textContent,
    endVisible: !document.querySelector('#end')?.classList.contains('hidden')
  }));
  console.log(label, 'stats', JSON.stringify(stat));
  console.log(label, 'errors', errs);
  await ctx.close();
}

await run('portrait', {width:390,height:844});
await run('landscape', {width:844,height:390});
await browser.close();

