  await page.waitForTimeout(500);
  const toPage = await page.evaluate(()=>{
    const r=document.getElementById('stage').getBoundingClientRect();
    const a=window.SCHULTAG.state.a3;
    const map=b=>({x:r.left+b.x/960*r.width, y:r.top+330/540*r.height});
    return Object.fromEntries(a.bottles.map(b=>[b.id,map(b)]));
  });
  await page.mouse.click(toPage.kaffee.x, toPage.kaffee.y);
  await page.waitForTimeout(200);
  console.log('desktop wrong phase', await page.evaluate(()=>window.SCHULTAG.state.a3.phase));
  await page.waitForTimeout(1900);
  console.log('desktop retry', JSON.stringify(await page.evaluate(()=>({phase:window.SCHULTAG.state.a3.phase, panel:!document.getElementById('choicePanel').classList.contains('hidden'), wrong:window.SCHULTAG.state.stats.wrong}))));
  const tod = await page.evaluate(()=>{
    const r=document.getElementById('stage').getBoundingClientRect();
    const b=window.SCHULTAG.state.a3.bottles.find(x=>x.id==='tod');
    return {x:r.left+b.x/960*r.width, y:r.top+330/540*r.height};
  });
  await page.mouse.click(tod.x, tod.y);
  await page.waitForTimeout(200);
  console.log('desktop tod', await page.evaluate(()=>window.SCHULTAG.state.a3.phase));
  console.log('desktop errors', errs);
  await page.close();
}

// Mobile: touch hold stare, touch steer, wrong potion retry
{
  const ctx = await browser.newContext({ viewport:{width:390,height:844}, isMobile:true, hasTouch:true, deviceScaleFactor:2 });
