  await page.locator('#actBtn').dispatchEvent('pointerup', { pointerType:'touch', bubbles:true, isPrimary:true });
  console.log('mobile stare', JSON.stringify(await page.evaluate(()=>({scene:window.SCHULTAG.scene, stare:window.SCHULTAG.state.stats.stare, phase:window.SCHULTAG.state.a1.phase}))));
